(() => {
  'use strict';
  const seed = window.AUDIT_SEED;
  const KEY = 'payeshban.audit.v1';
  const defaultState = { year: seed.defaultYear, years: [...seed.years], overrides: {}, weightOverrides: {}, criteriaOverrides: {}, comments: {}, deletedCriteria: [], addedCriteria: [], addedCompanies: [] };
  const cloudConfig=window.PAYESHBAN_SUPABASE||{};
  const cloudClient=window.supabase?.createClient&&cloudConfig.url&&cloudConfig.publishableKey?window.supabase.createClient(cloudConfig.url,cloudConfig.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;
  let store = loadStore();
  let view = 'dashboard';
  let selectedCompany = seed.companies[0]?.id;
  let companyQuery = '';
  let companyFilter = 'all';
  let sectionFilter = 'environment';
  let toastTimer;
  let authSession=null,cloudReady=false,cloudDirty=false,cloudRevision=0,cloudSyncBusy=false,cloudSyncQueued=false,cloudSyncTimer=null,realtimeChannel=null,activatingSession=null;
  const $ = (s, r=document) => r.querySelector(s);
  const $$ = (s, r=document) => [...r.querySelectorAll(s)];
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = n => n===null||n===undefined||n===''||!Number.isFinite(Number(n)) ? '—' : Number(n).toLocaleString('fa-IR',{maximumFractionDigits:2});
  const fmtWeight = n => n===null||n===undefined||n===''||!Number.isFinite(Number(n)) ? '—' : Number(n).toLocaleString('fa-IR',{maximumFractionDigits:4});
  const pct = n => Number.isFinite(Number(n)) ? `${Number(n).toLocaleString('fa-IR',{maximumFractionDigits:0})}٪` : '—';
  const normalizeDecimalInput = value => String(value ?? '').replace(/[۰-۹]/g,d=>String(d.charCodeAt(0)-0x06f0)).replace(/[٠-٩]/g,d=>String(d.charCodeAt(0)-0x0660)).replace(/[٫،,]/g,'.').replace(/\s/g,'');
  const parseRatingInput = value => { const normalized=normalizeDecimalInput(value); if(normalized==='')return null; if(!/^(?:\d+(?:\.\d*)?|\.\d+)$/.test(normalized))return NaN; return Number(normalized); };
  const sectionNames = Object.fromEntries(seed.sections.map(s => [s.id,s.name]));
  const section = id => seed.sections.find(s=>s.id===id);
  const allCompanies = () => [...seed.companies,...store.addedCompanies];
  function currentJalaliYear(){try{return Number(new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric'}).formatToParts(new Date()).find(p=>p.type==='year')?.value)||1405;}catch{return 1405;}}
  const futureYears=()=>Array.from({length:11},(_,i)=>String(currentJalaliYear()+i));
  const roundWeight=n=>Math.round((Number(n)||0)*1e6)/1e6;
  const commentKey=(year,companyId,itemId)=>`${year}|${companyId}|${itemId}`;
  const commentText=(year,companyId,itemId)=>store.comments[commentKey(year,companyId,itemId)]||'';
  function loadStore(){ try { const v=JSON.parse(localStorage.getItem(KEY)||'null'); return v&&typeof v==='object'?{...structuredClone(defaultState),...v,overrides:v.overrides||{},weightOverrides:v.weightOverrides||{},criteriaOverrides:v.criteriaOverrides||{},comments:v.comments||{},deletedCriteria:v.deletedCriteria||[],years:v.years||[...seed.years],addedCriteria:v.addedCriteria||[],addedCompanies:v.addedCompanies||[]}:structuredClone(defaultState); } catch { return structuredClone(defaultState); } }
  function persistLocal(){localStorage.setItem(KEY,JSON.stringify(store));}
  function setCloudStatus(text,state='saved'){const el=$('#saveIndicator');if(!el)return;el.classList.toggle('saved',state==='saved');el.classList.toggle('sync-error',state==='error');el.innerHTML=`<i></i><span>${esc(text)}</span>`;}
  function persist(){persistLocal();if(cloudReady){cloudDirty=true;queueCloudSync();}else setCloudStatus('پشتیبان محلی ذخیره شد','saved');}
  function normalizeWeightsForYear(year){const items=allCriteria('environment');if(!items.length)return false;const values=items.map(it=>Math.max(0,Number(weight(year,it))||0));const total=values.reduce((a,b)=>a+b,0);if(Math.abs(total-100)<1e-7)return false;const scaled=values.map(v=>roundWeight(total>0?v*100/total:100/items.length));const correction=roundWeight(100-scaled.reduce((a,b)=>a+b,0));let adjust=values.indexOf(Math.max(...values));if(adjust<0)adjust=0;scaled[adjust]=roundWeight(scaled[adjust]+correction);items.forEach((it,i)=>{store.weightOverrides[`${year}|${it.id}`]=scaled[i];});return true;}
  function enforceAllEnvironmentWeights(){const years=[...new Set([...seed.years,...store.years,String(store.year),...futureYears()])];let changed=false;for(const year of years)changed=normalizeWeightsForYear(year)||changed;return changed;}
  function setBalancedWeight(year,itemId,targetValue){const items=allCriteria('environment');normalizeWeightsForYear(year);const anchor=items.find(it=>it.id===itemId);if(!anchor)return;const target=roundWeight(Math.max(0,Math.min(100,Number(targetValue)||0))),others=items.filter(it=>it.id!==itemId);store.weightOverrides[`${year}|${itemId}`]=target;if(!others.length)return;const old=others.map(it=>Math.max(0,Number(weight(year,it))||0)),total=old.reduce((a,b)=>a+b,0),remaining=roundWeight(100-target);const next=old.map(v=>roundWeight(total>0?v*remaining/total:remaining/others.length));const correction=roundWeight(remaining-next.reduce((a,b)=>a+b,0));let adjust=old.indexOf(Math.max(...old));if(adjust<0)adjust=0;next[adjust]=roundWeight(next[adjust]+correction);others.forEach((it,i)=>{store.weightOverrides[`${year}|${it.id}`]=next[i];});}
  function redistributeDeletedWeight(item){for(const year of [...new Set([...seed.years,...store.years,String(store.year),...futureYears()])]){normalizeWeightsForYear(year);const removed=Math.max(0,Number(weight(year,item))||0);if(!removed)continue;const recipients=allCriteria('environment').filter(it=>it.id!==item.id).sort((a,b)=>(Number(weight(year,b))||0)-(Number(weight(year,a))||0)).slice(0,4);if(!recipients.length)continue;const share=roundWeight(removed/recipients.length);recipients.forEach(it=>{store.weightOverrides[`${year}|${it.id}`]=roundWeight((Number(weight(year,it))||0)+share);});const remainingTotal=allCriteria('environment').filter(it=>it.id!==item.id).reduce((sum,it)=>sum+(Number(weight(year,it))||0),0),correction=roundWeight(100-remainingTotal);if(correction)store.weightOverrides[`${year}|${recipients[0].id}`]=roundWeight((Number(weight(year,recipients[0]))||0)+correction);}}
  function normalizeStore(value){const v=value&&typeof value==='object'?value:{};return {...structuredClone(defaultState),...v,overrides:v.overrides||{},weightOverrides:v.weightOverrides||{},criteriaOverrides:v.criteriaOverrides||{},comments:v.comments||{},deletedCriteria:Array.isArray(v.deletedCriteria)?v.deletedCriteria:[],years:Array.isArray(v.years)?v.years:[...seed.years],addedCriteria:Array.isArray(v.addedCriteria)?v.addedCriteria:[],addedCompanies:Array.isArray(v.addedCompanies)?v.addedCompanies:[]};}
  function hasLocalChanges(value){const v=normalizeStore(value);return Object.keys(v.overrides).length>0||Object.keys(v.weightOverrides).length>0||Object.keys(v.criteriaOverrides).length>0||Object.keys(v.comments).length>0||v.deletedCriteria.length>0||v.addedCriteria.length>0||v.addedCompanies.length>0||v.year!==seed.defaultYear||v.years.some(y=>!seed.years.includes(y));}
  function mergeStores(remoteValue,localValue){const remote=normalizeStore(remoteValue),local=normalizeStore(localValue);const byId=(a,b)=>[...new Map([...a,...b].map(x=>[x.id,x])).values()];return {...remote,...local,years:[...new Set([...remote.years,...local.years])],overrides:{...remote.overrides,...local.overrides},weightOverrides:{...remote.weightOverrides,...local.weightOverrides},criteriaOverrides:{...remote.criteriaOverrides,...local.criteriaOverrides},comments:{...remote.comments,...local.comments},deletedCriteria:[...new Set([...remote.deletedCriteria,...local.deletedCriteria])],addedCriteria:byId(remote.addedCriteria,local.addedCriteria),addedCompanies:byId(remote.addedCompanies,local.addedCompanies)};}
  function queueCloudSync(delay=650){if(!cloudReady)return;if(cloudSyncTimer)clearTimeout(cloudSyncTimer);setCloudStatus('در حال همگام‌سازی…','saving');cloudSyncTimer=setTimeout(()=>syncCloud(),delay);}
  async function syncCloud(){if(!cloudReady||!cloudClient)return;if(cloudSyncBusy){cloudSyncQueued=true;return;}cloudSyncBusy=true;try{for(let attempt=0;attempt<4;attempt++){const {data:row,error:readError}=await cloudClient.from('audit_workspace').select('payload,revision,updated_at,updated_by').eq('id','shared').maybeSingle();if(readError)throw readError;if(!row)throw new Error('اجازهٔ دسترسی به فضای ممیزی وجود ندارد.');if(Number(row.revision)>cloudRevision){store=cloudDirty?mergeStores(row.payload,store):normalizeStore(row.payload);cloudRevision=Number(row.revision);persistLocal();render();}const next=Number(row.revision)+1;const {data:saved,error:writeError}=await cloudClient.from('audit_workspace').update({payload:store,revision:next,updated_at:new Date().toISOString(),updated_by:authSession?.user?.id||null}).eq('id','shared').eq('revision',Number(row.revision)).select('revision').maybeSingle();if(writeError)throw writeError;if(saved){cloudRevision=Number(saved.revision);cloudDirty=false;setCloudStatus('در فضای ابری ذخیره شد','saved');return;}}throw new Error('تغییر هم‌زمان دیگر کاربران را همگام نکردم؛ دوباره تلاش کنید.');}catch(error){console.error('Cloud sync failed:',error?.message||error);setCloudStatus('خطا در همگام‌سازی','error');toast('ذخیرهٔ ابری انجام نشد؛ اتصال را بررسی کنید.','error');}finally{cloudSyncBusy=false;if(cloudSyncQueued){cloudSyncQueued=false;queueCloudSync(250);}}}
  function showAuth(message='',kind='info'){const root=$('#authRoot'),shell=$('#appShell');if(shell)shell.hidden=true;if(!root)return;root.hidden=false;const email=authSession?.user?.email||'';root.innerHTML=`<main class="auth-card" dir="rtl"><div class="auth-brand"><div class="auth-mark">✓</div><div><strong>پایش‌بان</strong><small>سامانهٔ ممیزی پتروشیمی‌های عسلویه</small></div></div><div class="auth-eyebrow">ورود اختیاری برای فضای کاری مشترک</div><h1>${email?'بررسی دسترسی':'ورود برای همگام‌سازی'}</h1><p class="auth-description">برای دیدن سامانه نیازی به ورود نیست. با ایمیل کاری مجاز وارد شوید تا تغییرها در فضای ابری ذخیره و با همکاران همگام شوند.</p>${message?`<div class="auth-message ${kind}">${esc(message)}</div>`:''}${email?`<div class="auth-current"><span>حساب فعلی</span><strong>${esc(email)}</strong><button class="btn btn-outline btn-sm" id="authSignout">خروج و تغییر حساب</button></div>`:`<form id="loginForm" class="auth-form"><label for="loginEmail">ایمیل کاری</label><input id="loginEmail" type="email" inputmode="email" autocomplete="email" required placeholder="name@company.com"><button class="btn btn-primary" id="loginSubmit" type="submit">ارسال لینک امن ورود <span>←</span></button><small>لینک یک‌بارمصرف فقط برای فعال‌کردن ذخیره و همگام‌سازی مشترک است.</small></form>`}<button class="btn btn-outline guest-continue" id="guestContinue" type="button">بازگشت به مشاهدهٔ سامانه</button><div class="auth-footer">ورود اختیاری است؛ کاربران بدون ورود فقط نسخهٔ محلی همین مرورگر را می‌بینند.</div></main>`;const form=$('#loginForm');if(form)form.onsubmit=async event=>{event.preventDefault();const email=$('#loginEmail').value.trim().toLowerCase(),button=$('#loginSubmit');button.disabled=true;button.textContent='در حال ارسال…';const {error}=await cloudClient.auth.signInWithOtp({email,options:{emailRedirectTo:`${window.location.origin}${window.location.pathname}`,shouldCreateUser:true}});if(error){showAuth(error.message,'error');return;}showAuth(`لینک یک‌بارمصرف به ${email} ارسال شد. ایمیل را در همین مرورگر باز کنید.`,'success');};const back=$('#guestContinue');if(back)back.onclick=()=>showGuest();const signout=$('#authSignout');if(signout)signout.onclick=async()=>{await cloudClient?.auth.signOut();};}
  function attachRealtime(){if(!cloudClient)return;if(realtimeChannel)cloudClient.removeChannel(realtimeChannel);realtimeChannel=cloudClient.channel('payeshban-audit-workspace').on('postgres_changes',{event:'UPDATE',schema:'public',table:'audit_workspace',filter:'id=eq.shared'},event=>{const row=event.new;if(!row||Number(row.revision)<=cloudRevision)return;store=cloudDirty?mergeStores(row.payload,store):normalizeStore(row.payload);cloudRevision=Number(row.revision);persistLocal();render();if(cloudDirty)queueCloudSync(250);else setCloudStatus('تغییرهای اعضا همگام شد','saved');}).subscribe();}
  async function activateSession(session){if(!cloudClient||!session)return;if(activatingSession)return activatingSession;activatingSession=(async()=>{authSession=session;cloudReady=false;showAuth('در حال بررسی دسترسی و دریافت اطلاعات مشترک…');try{const {data:row,error}=await cloudClient.from('audit_workspace').select('payload,revision').eq('id','shared').maybeSingle();if(error)throw error;if(!row){await cloudClient.auth.signOut();showGuest();toast('این ایمیل مجاز به فضای ابری نیست؛ سامانه در حالت مشاهده باز شد.','error');return;}const local=store;store=hasLocalChanges(row.payload)?normalizeStore(row.payload):mergeStores(row.payload,local);const weightsChanged=enforceAllEnvironmentWeights();cloudRevision=Number(row.revision)||1;cloudReady=true;cloudDirty=weightsChanged||(!hasLocalChanges(row.payload)&&hasLocalChanges(local));persistLocal();const shell=$('#appShell'),root=$('#authRoot'),user=$('#cloudUser'),logout=$('#logoutBtn'),login=$('#loginBtn');if(root)root.hidden=true;if(shell)shell.hidden=false;if(user){user.textContent=session.user?.email||'';user.hidden=false;}if(logout)logout.hidden=false;if(login)login.hidden=true;attachRealtime();render();setCloudStatus(cloudDirty?'در حال همگام‌سازی وزن‌ها':'همگام‌سازی ابری فعال',cloudDirty?'saving':'saved');if(cloudDirty)queueCloudSync(100);}catch(error){console.error('Workspace load failed:',error?.message||error);showGuest();toast('اتصال ابری برقرار نشد؛ سامانه در حالت محلی باز شد.','error');}})().finally(()=>{activatingSession=null;});return activatingSession;}
  function showGuest(){authSession=null;cloudReady=false;const weightsChanged=enforceAllEnvironmentWeights();if(weightsChanged)persistLocal();const root=$('#authRoot'),shell=$('#appShell'),user=$('#cloudUser'),logout=$('#logoutBtn'),login=$('#loginBtn');if(root)root.hidden=true;if(shell)shell.hidden=false;if(user){user.textContent='مشاهدهٔ مهمان';user.hidden=false;}if(logout)logout.hidden=true;if(login)login.hidden=!cloudClient;render();setCloudStatus('ذخیرهٔ محلی · ورود برای همگام‌سازی','saved');}
  function startAuth(){const shell=$('#appShell');if(shell)shell.hidden=true;const login=$('#loginBtn');if(login)login.onclick=()=>showAuth();if(!cloudClient){showGuest();return;}cloudClient.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_IN'&&session)window.setTimeout(()=>activateSession(session),0);if(event==='SIGNED_OUT'){authSession=null;cloudReady=false;cloudRevision=0;if(realtimeChannel){cloudClient.removeChannel(realtimeChannel);realtimeChannel=null;}const user=$('#cloudUser'),logout=$('#logoutBtn');if(user)user.hidden=true;if(logout)logout.hidden=true;showGuest();}});cloudClient.auth.getSession().then(({data,error})=>{if(error){showGuest();return;}if(data.session)activateSession(data.session);else showGuest();}).catch(()=>showGuest());}
  function allCriteria(sectionId){ const items=[...(section(sectionId)?.criteria||[]).map(x=>({...x,...(store.criteriaOverrides[x.id]||{})})),...store.addedCriteria.filter(x=>x.sectionId===sectionId)].filter(x=>!store.deletedCriteria.includes(x.id));const groups=new Map();for(const it of items){if(!groups.has(it.categoryId))groups.set(it.categoryId,[]);groups.get(it.categoryId).push(it);}return [...groups.values()].flat(); }
  function zeroDefaultCompany(year,companyId,sectionId='environment'){return sectionId==='environment'&&Number(year)>=Number(seed.defaultYear)&&seed.companies.some(c=>c.id===companyId)&&!seed.importedCompanyIds.includes(companyId);}
  function rating(year,companyId,item,sectionId='environment'){ const k=`${year}|${companyId}|${item.id}`; if(Object.prototype.hasOwnProperty.call(store.overrides,k)) return store.overrides[k]; if(year==='1404'&&item.ratings?.[companyId]!=null) return item.ratings[companyId]; return zeroDefaultCompany(year,companyId,sectionId)?0:null; }
  function ratingEntered(year,companyId,item){const k=`${year}|${companyId}|${item.id}`;if(Object.prototype.hasOwnProperty.call(store.overrides,k))return store.overrides[k]!==null&&store.overrides[k]!=='';return year==='1404'&&item.ratings?.[companyId]!=null;}
  function weight(year,item){const k=`${year}|${item.id}`;return Object.prototype.hasOwnProperty.call(store.weightOverrides,k)?store.weightOverrides[k]:item.weight;}
  function totalWeight(year,sectionId='environment'){return allCriteria(sectionId).reduce((sum,it)=>sum+(Number(weight(year,it))||0),0);}
  function isTouched(year,companyId,sectionId){ return allCriteria(sectionId).some(it=>Object.prototype.hasOwnProperty.call(store.overrides,`${year}|${companyId}|${it.id}`)); }
  function scoreInfo(year,companyId,sectionId='environment'){
    const items=allCriteria(sectionId); let points=0,answered=0,max=0;
    for(const it of items){ const w=Number(weight(year,it)); if(Number.isFinite(w)&&w>0)max+=w; const r=rating(year,companyId,it,sectionId); if(r!==null&&r!==''&&Number.isFinite(Number(r))&&Number.isFinite(w)&&w>0){points+=Number(r)*w;if(ratingEntered(year,companyId,it))answered++;} }
    const zeroDefault=zeroDefaultCompany(year,companyId,sectionId);
    const hasCalculated=answered>0||zeroDefault;
    const c=allCompanies().find(x=>x.id===companyId);
    const legacy=sectionId==='environment'?(c?.scores?.[year] ?? null):null;
    const seeded=year==='1404'&&seed.importedCompanyIds.includes(companyId)&&answered>0;
    const score=hasCalculated?points:(legacy!==null?Number(legacy):null);
    return {score,points,max,answered,totalItems:items.filter(it=>Number(weight(year,it))>0).length,hasCalculated,legacy:!hasCalculated&&legacy!==null,seeded,zeroDefault};
  }
  function ratedCompanies(year,sectionId='environment') { return allCompanies().map(c=>({company:c,...scoreInfo(year,c.id,sectionId)})).filter(x=>x.score!==null).sort((a,b)=>b.score-a.score); }
  function toast(message,type='success'){const root=$('#toastRoot');const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;root.append(el);setTimeout(()=>el.remove(),2800);}
  function nav(){
    const links=[['dashboard','⌂','داشبورد'],['companies','▦','شرکت‌ها'],['environment','◉','محیط زیست']];
    const others=[['health','＋','بهداشت'],['safety','＋','ایمنی'],['crisis','＋','مدیریت بحران'],['fire','＋','آتش‌نشانی']];
    const main=$('#mainNav'); main.innerHTML=`<div class="nav-list">${links.map(([id,icon,label])=>`<button class="nav-item ${view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span><span class="nav-text">${label}</span>${id==='environment'?`<span class="nav-pill">۳۶</span>`:''}</button>`).join('')}<div class="nav-separator"></div>${others.map(([id,icon,label])=>`<button class="nav-item ${view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span><span class="nav-text">${label}</span><span class="nav-pill">خالی</span></button>`).join('')}<div class="nav-separator"></div><button class="nav-item ${view==='criteria'?'active':''}" data-view="criteria"><span class="nav-icon">☷</span><span class="nav-text">مدیریت بندها</span></button><button class="nav-item ${view==='data'?'active':''}" data-view="data"><span class="nav-icon">⇧</span><span class="nav-text">پشتیبان و داده‌ها</span></button></div>`;
  }
  function fillYears(){const sel=$('#yearSelect');const years=[...new Set([...seed.years,...store.years,...futureYears()])].sort((a,b)=>Number(b)-Number(a)); if(!years.includes(store.year))years.unshift(store.year);sel.innerHTML=years.map(y=>`<option value="${esc(y)}" ${y===store.year?'selected':''}>${esc(y)}</option>`).join('');}
  function pageHeading(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">مرکز پایش و ارزیابی</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
  function avgScore(list){const a=list.filter(x=>x.score!==null);return a.length?a.reduce((s,x)=>s+x.score,0)/a.length:null;}
  function dashboard(){
    const rank=ratedCompanies(store.year); const imported=rank.filter(x=>x.seeded).length; const mean=avgScore(rank); const companies=allCompanies(); const top=rank.slice(0,6); const n=rank.length;
    const section=seed.sections.find(s=>s.id==='environment');
    const counts={}; for(const c of companies){const info=scoreInfo(store.year,c.id);counts[c.id]=info;}
    const avgPrev=avgScore(companies.map(c=>({score:c.scores?.['1403']??null})).filter(x=>x.score!==null));
    const dashboardActions=`<button class="btn btn-outline" data-action="report" data-section="environment">▤ گزارش محیط‌زیست</button><button class="btn btn-primary" data-view="environment">ورود به ممیزی <span>←</span></button>`;
    return `${pageHeading('داشبورد ممیزی','نمای کلی عملکرد ممیزی شرکت‌های پتروشیمی منطقه عسلویه در سال انتخاب‌شده.',dashboardActions)}
      <section class="hero-panel"><div class="hero-content"><div class="hero-kicker"><span></span> پایش سالانهٔ HSE · سال ${esc(store.year)}</div><h2>ارزیابی دقیق، تصمیم‌گیری مطمئن</h2><p>تصویر یکپارچهٔ نتایج ممیزی محیط‌زیست شرکت‌ها؛ از ثبت بندها تا مقایسهٔ عملکرد و تهیهٔ گزارش رسمی.</p></div><div class="hero-stats"><div class="hero-stat"><strong>${fmt(companies.length)}</strong><small>شرکت در فهرست</small></div><div class="hero-stat"><strong>${fmt(n)}</strong><small>دارای امتیاز</small></div><div class="hero-stat"><strong>${fmt(imported)}</strong><small>دارای جزئیات بندها</small></div></div><div class="hero-mark">✓</div></section>
      <section class="kpi-grid"><article class="kpi-card"><div class="kpi-icon">▦</div><div class="kpi-copy"><small>شرکت‌های فهرست‌شده</small><strong>${fmt(companies.length)} <em>شرکت</em></strong></div></article><article class="kpi-card"><div class="kpi-icon amber">★</div><div class="kpi-copy"><small>میانگین نمرهٔ ثبت‌شده</small><strong>${mean===null?'—':fmt(mean)} <em>از ۱۰۰</em></strong></div></article><article class="kpi-card"><div class="kpi-icon blue">✓</div><div class="kpi-copy"><small>جزئیات کامل در اکسل</small><strong>${fmt(imported)} <em>شرکت</em></strong></div></article><article class="kpi-card"><div class="kpi-icon purple">↗</div><div class="kpi-copy"><small>میانگین سال ${store.year==='1404'?'۱۴۰۳':'۱۴۰۴'}</small><strong>${avgPrev===null?'—':fmt(avgPrev)} <em>از ۱۰۰</em></strong></div></article></section>
      <section class="dashboard-grid"><article class="panel"><div class="panel-head"><div><h2 class="panel-title">مقایسهٔ امتیاز شرکت‌ها</h2><div class="panel-subtitle">نمرهٔ کل محیط‌زیست · سال ${esc(store.year)}</div></div><button class="btn btn-outline btn-sm" data-view="companies">همهٔ شرکت‌ها ←</button></div><div class="panel-body"><div class="chart-bars">${top.length?top.map(x=>bar(x.company.name,x.score)).join(''):'<div class="empty-state">هنوز امتیازی برای این سال ثبت نشده است.</div>'}</div></div></article>
      <article class="panel"><div class="panel-head"><div><h2 class="panel-title">رتبه‌های برتر</h2><div class="panel-subtitle">بر پایهٔ امتیاز کل فعلی</div></div><span class="status-tag">${esc(store.year)}</span></div><div class="panel-body"><div class="rank-list">${top.slice(0,5).map((x,i)=>`<div class="rank-row"><div class="rank-number">${fmt(i+1)}</div><div><div class="rank-name">${esc(x.company.name)}</div><div class="rank-detail">${x.seeded||x.zeroDefault||x.hasCalculated?'امتیاز محاسبه‌شده از بندها':'امتیاز کل ثبت‌شده در اکسل'}</div></div><div class="rank-score">${fmt(x.score)}</div></div>`).join('')||'<div class="empty-state">داده‌ای برای رتبه‌بندی موجود نیست.</div>'}</div></div></article></section>
      <div class="section-strip"><div><h2>فهرست شرکت‌ها</h2><p>انتخاب هر شرکت برای ورود به جزئیات ممیزی</p></div><button class="btn btn-outline btn-sm" data-view="companies">مدیریت شرکت‌ها</button></div><div class="company-grid">${companies.slice(0,12).map(c=>companyCard(c,counts[c.id])).join('')}</div><div class="section-strip"><div><h2>حوزه‌های ممیزی</h2><p>محیط‌زیست فعال است؛ سایر حوزه‌ها برای تکمیل آینده آماده‌اند.</p></div></div><div class="company-grid section-shortcuts">${seed.sections.map(s=>`<button class="company-card" data-view="${s.id}"><div class="company-card-head"><span class="company-name">${esc(s.name)}</span><span class="status-tag ${s.id==='environment'?'':'pending'}">${s.id==='environment'?'فعال':'آمادهٔ تکمیل'}</span></div><div class="company-meta"><span>${allCriteria(s.id).length?fmt(allCriteria(s.id).length)+' بند':'هنوز بندی تعریف نشده'}</span><span>گزارش PDF ←</span></div></button>`).join('')}</div>`;
  }
  function bar(name,value){const v=Math.max(0,Math.min(100,Number(value)||0));return `<div class="bar-row"><span class="bar-name">${esc(name)}</span><div class="bar-track"><div class="bar-fill ${v<70?'low':''}" style="width:${v}%"></div></div><span class="bar-value">${fmt(value)}</span></div>`;}
  function companyCard(c,info=scoreInfo(store.year,c.id)){const status=info.seeded?'بندها وارد شده':info.zeroDefault?'شروع از صفر · امتیاز از بندها':info.legacy?'فقط نمرهٔ کل':'در انتظار ممیزی';return `<button class="company-card" data-company="${esc(c.id)}"><div class="company-card-head"><span class="company-name">${esc(c.name)}</span><span class="company-score ${info.score===null?'no-score':''}">${fmt(info.score)}</span></div><div class="company-meta"><span>${status}</span><span>${info.score===null?'':'از ۱۰۰'}</span></div></button>`;}
  function companyList(){const list=allCompanies().filter(c=>c.name.includes(companyQuery));return `<div class="panel company-list-panel"><div class="panel-head"><div><h2 class="panel-title">شرکت‌ها</h2><div class="panel-subtitle">${fmt(list.length)} مورد</div></div></div><div class="company-list-scroll">${list.map(c=>{const inf=scoreInfo(store.year,c.id);return `<button class="company-list-item ${selectedCompany===c.id?'active':''}" data-company="${esc(c.id)}"><span class="company-avatar">${esc(c.name.slice(0,1))}</span><span class="company-list-copy"><strong>${esc(c.name)}</strong><small>${inf.seeded?'امتیاز بندها':inf.zeroDefault?'شروع از صفر':inf.legacy?'نمرهٔ اکسل':'بدون امتیاز'}</small></span><span class="company-list-score">${fmt(inf.score)}</span></button>`}).join('')||'<p class="panel-subtitle" style="padding:15px">موردی پیدا نشد.</p>'}</div></div>`;}
  function companyPage(){const c=allCompanies().find(x=>x.id===selectedCompany)||allCompanies()[0];if(!c)return '<div class="empty-state">شرکتی برای نمایش وجود ندارد.</div>';const info=scoreInfo(store.year,c.id);const detailed=seed.importedCompanyIds.includes(c.id);const items=allCriteria('environment');const answered=items.filter(it=>Number(weight(store.year,it))>0&&ratingEntered(store.year,c.id,it)).length;const dataImported=store.year==='1404'&&detailed;
    const notice=info.zeroDefault?`<div class="notice"><span class="notice-icon">ⓘ</span><div><strong>در فایل مبنا فقط نمرهٔ کل این شرکت موجود بود؛ ارزیابی این سال از صفر آغاز شده است.</strong>مقدار هر بند فعلاً ۰ است و نمرهٔ کل از مجموع (نتیجهٔ ارزیابی × وزن بند) محاسبه می‌شود. با تغییر نمرهٔ هر بند، نمرهٔ کل بلافاصله به‌روزرسانی خواهد شد؛ نمرهٔ کل قدیمی اکسل در محاسبهٔ این سال استفاده نمی‌شود.</div></div>`:(!detailed&&info.legacy?`<div class="notice"><span class="notice-icon">ⓘ</span><div><strong>در فایل مبنا فقط نمرهٔ کل این شرکت ثبت شده بود.</strong>عدد ${fmt(info.score)} از شیت خلاصه حفظ شده است؛ ریزنمرهٔ بندها در فایل وجود نداشت. با ورود اولین بند، محاسبهٔ این صفحه بر اساس داده‌های بندها انجام می‌شود.</div></div>`:(!dataImported&&store.year==='1404'&&detailed?`<div class="notice"><span class="notice-icon">ⓘ</span><div><strong>برای سال ${store.year} دادهٔ ردیفی از اکسل وارد نشده است.</strong>امتیازهای سال‌های دیگر فقط برای مقایسه‌اند؛ نمرهٔ امسال را از بندها ثبت کنید.</div></div>`:''));
    return `${pageHeading('ممیزی محیط‌زیست','مجموع وزن‌ها در هر سال دقیقاً ۱۰۰ است؛ با تغییر وزن یک بند، وزن سایر بندها به نسبت فعلی تعدیل می‌شود.',`<button class="btn btn-outline" data-action="company-report" data-report-company="${esc(c.id)}">⇩ PDF همین شرکت</button><button class="btn btn-outline" data-action="report" data-section="environment">▤ گزارش همهٔ شرکت‌ها</button><button class="btn btn-primary" data-action="focus-score">ذخیره و ادامه</button>`)}
      <div class="toolbar"><label class="search-box"><span>⌕</span><input id="companySearch" placeholder="جست‌وجوی شرکت…" value="${esc(companyQuery)}"></label><span class="status-tag">${fmt(items.length)} بند محیط‌زیست</span><span class="status-tag weight-total-tag">مجموع وزن: ${fmtWeight(totalWeight(store.year))} از ۱۰۰</span></div>
      <div class="company-layout">${companyList()}<section class="panel score-panel"><div class="score-head"><div><h2>${esc(c.name)}</h2><p>سال ممیزی ${esc(store.year)} · ${dataImported?'اطلاعات ردیفی از فایل مبنا':'ثبت و تکمیل ممیزی'}</p></div><div class="score-total"><strong>${fmt(info.score)}</strong><small>${info.hasCalculated?'محاسبه‌شده از بندها':'امتیاز کل ثبت‌شده'} از ${fmt(info.max||100)}</small></div><div class="score-weight-total"><small>جمع وزن بندهای فعال</small><strong>${fmtWeight(totalWeight(store.year))} <span>از ۱۰۰</span></strong></div></div>${items.some(it=>Number(weight(store.year,it))>0)?`<div class="audit-progress"><div class="progress-track"><div class="progress-fill ${answered===0?'progress-empty':''}" style="width:${items.filter(it=>Number(weight(store.year,it))>0).length?answered/items.filter(it=>Number(weight(store.year,it))>0).length*100:0}%"></div></div><span>${fmt(answered)} از ${fmt(items.filter(it=>Number(weight(store.year,it))>0).length)} بند وزن‌دار نمره‌گذاری شده</span></div>`:''}${notice}${items.length?renderCriteriaForm(items,c.id):`<div class="empty-state"><div class="empty-icon">＋</div><h2>هنوز بندی تعریف نشده است</h2><p>معیارهای محیط‌زیست در فایل مبنا موجود است. از بخش «مدیریت بندها» معیار جدید اضافه کنید.</p><button class="btn btn-primary" data-view="criteria">مدیریت بندها</button></div>`}</section></div>`;
  }
  function renderCriteriaForm(items,companyId){
    let current='',currentName='',html='';
    for(let i=0;i<items.length;i++){
      const it=items[i];
      if(it.categoryId!==current){
        current=it.categoryId;currentName=it.categoryName||'سایر بندها';
        const group=items.filter(x=>x.categoryId===current);
        html+=`<div class="category-block" data-category="${esc(current)}"><div class="category-head"><h3>${esc(currentName)}</h3><small>${fmt(group.length)} بند · مجموع وزن: <span data-category-weight="${esc(current)}">${fmtWeight(group.reduce((sum,x)=>sum+(Number(weight(store.year,x))||0),0))}</span></small></div>`;
      }
      const r=rating(store.year,companyId,it),w=Number(weight(store.year,it));
      const points=r!==null&&r!==''&&w>0?Number(r)*w:null;
      const note=commentText(store.year,companyId,it.id),noteKey=commentKey(store.year,companyId,it.id);
      html+=`<div class="criterion-row" data-criterion-row="${esc(it.id)}"><div class="criterion-text"><span class="criterion-code">${esc(it.code||'جدید')}</span>${esc(it.question)}${!(w>0)?'<span class="criterion-note">وزن این بند صفر است؛ برای تخصیص وزن، مقدار را ویرایش کنید.</span>':''}<div class="criterion-actions-inline"><button class="btn btn-outline btn-sm" data-action="edit-criterion" data-section="environment" data-id="${esc(it.id)}">ویرایش بند</button><button class="btn btn-danger btn-sm" data-action="delete-criterion" data-section="environment" data-id="${esc(it.id)}">حذف بند</button></div></div><div class="criterion-edit-fields"><label class="edit-field"><span>نتیجه ارزیابی</span><input class="rating-input" type="text" inputmode="decimal" autocomplete="off" maxlength="8" placeholder="۰ تا ۱" aria-label="نتیجهٔ ارزیابی؛ عددی بین صفر و یک" title="فقط عدد بین ۰ و ۱ وارد کنید" data-rating="${esc(it.id)}" data-company="${esc(companyId)}" value="${r===null?'':String(r)}"></label><label class="edit-field"><span>وزن بند</span><input class="weight-input" type="number" min="0" max="100" step="0.0001" inputmode="decimal" placeholder="مثلاً ۳٫۵" aria-label="وزن بند؛ مجموع تمام بندها ۱۰۰ است" data-weight="${esc(it.id)}" value="${Number.isFinite(w)?String(w):'0'}"></label></div><div class="criterion-points"><strong data-points="${esc(it.id)}">${points===null?'—':fmt(points)}</strong><small>امتیاز بند</small></div></div><div class="criterion-comment"><div class="criterion-comment-head"><label for="comment-${esc(it.id)}">توضیحات ارزیاب</label><small><span data-comment-counter="${esc(noteKey)}">${fmt(note.length)}</span> / ۲۰۰۰ نویسه</small></div><textarea id="comment-${esc(it.id)}" maxlength="2000" rows="2" placeholder="توضیحات، شواهد یا اقدام اصلاحی مرتبط با این بند…" data-comment="${esc(it.id)}" data-company="${esc(companyId)}">${esc(note)}</textarea></div>`;
      const next=items[i+1];
      if(!next||next.categoryId!==current){
        html+=`<div class="criterion-add-row"><button class="btn btn-ghost btn-sm" data-action="add-criterion" data-section="environment" data-category-name="${esc(currentName)}">＋ افزودن بند به ${esc(currentName)}</button></div></div>`;
      }
    }
    return html;
  }
  function companiesPage(){const companies=allCompanies();const all=companies.map(c=>({c,i:scoreInfo(store.year,c.id)})).filter(x=>x.c.name.includes(companyQuery)).filter(x=>companyFilter==='all'||(companyFilter==='scored'?x.i.score!==null:x.i.seeded));return `${pageHeading('شرکت‌های ممیزی‌شونده','فهرست کامل شرکت‌های شیت مبنا و وضعیت ثبت نمرهٔ محیط‌زیست.',`<button class="btn btn-outline" data-action="report" data-section="environment">▤ گزارش و نمودار</button><button class="btn btn-primary" data-action="add-company">＋ افزودن شرکت</button>`)}<div class="toolbar"><label class="search-box"><span>⌕</span><input id="companySearch" placeholder="جست‌وجوی نام شرکت…" value="${esc(companyQuery)}"></label><select class="filter-select" id="companyFilter"><option value="all" ${companyFilter==='all'?'selected':''}>همهٔ شرکت‌ها</option><option value="scored" ${companyFilter==='scored'?'selected':''}>دارای امتیاز کل</option><option value="detailed" ${companyFilter==='detailed'?'selected':''}>دارای ریزنمره</option></select><span class="status-tag">${fmt(all.length)} شرکت</span></div><div class="company-grid">${all.map(x=>companyCard(x.c,x.i)).join('')||'<div class="panel empty-state">شرکتی با این مشخصات پیدا نشد.</div>'}</div>`;}
  function criterionManagementRow(it,sectionId){return `<div class="criteria-item"><span class="criteria-code">${esc(it.code||'جدید')}</span><span class="criteria-question">${esc(it.question)}</span><span class="criteria-weight">وزن: ${Number(weight(store.year,it))>0?fmtWeight(weight(store.year,it)):'—'}</span><span class="criteria-actions"><button class="btn btn-outline btn-sm" data-action="edit-criterion" data-section="${esc(sectionId)}" data-id="${esc(it.id)}">ویرایش</button><button class="btn btn-danger btn-sm" data-action="delete-criterion" data-section="${esc(sectionId)}" data-id="${esc(it.id)}">حذف</button></span></div>`;}
  function criteriaGroups(items){
    const groups=[];for(const it of items){let g=groups.find(x=>x.id===it.categoryId);if(!g){g={id:it.categoryId,name:it.categoryName||'سایر بندها',items:[]};groups.push(g);}g.items.push(it);}return groups;
  }
  function criteriaManagementGroups(items,sectionId){
    return criteriaGroups(items).map(g=>`<section class="criteria-category"><div class="category-head"><h3>${esc(g.name)}</h3><small>${fmt(g.items.length)} بند · مجموع وزن: ${fmtWeight(g.items.reduce((sum,it)=>sum+(Number(weight(store.year,it))||0),0))}</small></div><div class="criteria-list">${g.items.map(it=>criterionManagementRow(it,sectionId)).join('')}</div><div class="criterion-add-row"><button class="btn btn-ghost btn-sm" data-action="add-criterion" data-section="${esc(sectionId)}" data-category-name="${esc(g.name)}">＋ افزودن بند به ${esc(g.name)}</button></div></section>`).join('');
  }
  function sectionPage(id){
    const s=section(id),items=allCriteria(id);if(id==='environment')return companyPage();
    const actions=`<button class="btn btn-outline" data-action="report" data-section="${id}">▤ گزارش PDF</button>`;
    const list=items.length?`<div class="panel-head"><div><h2 class="panel-title">معیارهای ${esc(s.name)}</h2><div class="panel-subtitle">${fmt(items.length)} بند تعریف‌شده · امکان ویرایش یا حذف از هر ردیف</div></div></div><div class="panel-body">${criteriaManagementGroups(items,id)}</div>`:`<div class="empty-state"><div class="empty-icon">＋</div><h2>بخش ${esc(s.name)} هنوز خالی است</h2><p>برای شروع، یک دسته/عنوان تعریف کنید و اولین بند را به آن اضافه کنید.</p><button class="btn btn-primary" data-action="add-criterion" data-section="${id}">＋ افزودن اولین بند</button></div>`;
    return `${pageHeading(s.name,'بندهای ممیزی این حوزه را زیر عنوان‌های مربوط اضافه، ویرایش یا حذف کنید.',actions)}<div class="panel">${list}</div><div class="panel" style="margin-top:15px"><div class="panel-head"><div><h2 class="panel-title">سایر حوزه‌های ممیزی</h2><div class="panel-subtitle">حوزه‌ای را برای مدیریت بندهای آن انتخاب کنید.</div></div></div><div class="panel-body"><div class="company-grid">${seed.sections.map(x=>`<button class="company-card" data-view="${x.id}"><div class="company-card-head"><span class="company-name">${esc(x.name)}</span><span class="status-tag ${x.id===id?'':'pending'}">${x.id===id?'در حال مشاهده':'بازکردن'}</span></div><div class="company-meta"><span>${fmt(allCriteria(x.id).length)} بند تعریف‌شده</span><span>مدیریت ←</span></div></button>`).join('')}</div></div></div>`;
  }
  function criteriaPage(){
    const selected=sectionFilter;const items=allCriteria(selected);
    return `${pageHeading('مدیریت بندهای ممیزی','برای هر عنوان، بند جدید را پس از آخرین بند همان عنوان اضافه کنید؛ ویرایش و حذف از هر ردیف انجام می‌شود.') }<div class="toolbar"><select id="sectionFilter" class="filter-select">${seed.sections.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')}</select><span class="status-tag">${fmt(items.length)} بند</span></div><div class="panel">${items.length?`<div class="panel-head"><div><h2 class="panel-title">بندهای ${esc(sectionNames[selected])}</h2><div class="panel-subtitle">${fmt(criteriaGroups(items).length)} عنوان/دسته · برای هر دسته، افزودن بند در انتهای همان فهرست قرار دارد.</div></div></div><div class="panel-body">${criteriaManagementGroups(items,selected)}</div>`:`<div class="empty-state"><div class="empty-icon">☷</div><h2>برای ${esc(sectionNames[selected])} بندی ثبت نشده</h2><p>برای شروع یک بند ایجاد کنید و عنوان/دستهٔ آن را مشخص کنید.</p><button class="btn btn-primary" data-action="add-criterion" data-section="${selected}">＋ افزودن اولین بند</button></div>`}</div>${selected==='environment'?`<div class="notice" style="margin-top:14px"><span class="notice-icon">ⓘ</span><div><strong>دادهٔ ردیفی شیت مبنا</strong>برای ۱۲ شرکت، امتیازهای محیط‌زیست به تفکیک بند موجود بود و همان امتیازها وارد شده‌اند. برای سایر شرکت‌ها، شیت مبنا فقط امتیاز کل را داشت.</div></div>`:''}`;
  }
  function dataPage(){return `${pageHeading('پشتیبان و داده‌ها','پشتیبان‌گیری، بازیابی و وضعیت فضای کاری مشترک.',`<button class="btn btn-outline" data-action="export-data">⇩ دریافت نسخهٔ پشتیبان</button>`)}<div class="panel"><div class="panel-head"><div><h2 class="panel-title">مدیریت اطلاعات</h2><div class="panel-subtitle">داده‌های ممیزی برای اعضای مجاز در فضای ابری مشترک نگهداری می‌شود.</div></div></div><div class="panel-body"><div class="setting-row"><div><strong>وضعیت اتصال</strong><small>${cloudReady?'اطلاعات این نشست به Supabase متصل و همگام می‌شود.':'اتصال ابری در دسترس نیست.'}</small></div><span class="status-tag ${cloudReady?'':'pending'}">${cloudReady?'آنلاین':'آفلاین'}</span></div><div class="setting-row"><div><strong>خروجی پشتیبان JSON</strong><small>شامل نمره‌ها، وزن‌ها، سال‌ها و تغییرهای بندها</small></div><button class="btn btn-primary btn-sm" data-action="export-data">دانلود فایل</button></div><div class="setting-row"><div><strong>بازیابی از فایل پشتیبان</strong><small>فایل JSON صادرشده از همین سامانه را انتخاب کنید؛ پس از بازیابی برای اعضا همگام می‌شود.</small></div><label class="btn btn-outline btn-sm">انتخاب فایل<input id="importFile" type="file" accept="application/json" hidden></label></div><div class="setting-row"><div><strong>سال‌های ممیزی</strong><small>${store.years.map(esc).join('، ')}</small></div><button class="btn btn-outline btn-sm" data-action="new-year">＋ افزودن سال</button></div></div></div><div class="notice" style="margin-top:14px"><span class="notice-icon">ⓘ</span><div><strong>همکاری چندکاربره</strong>هر تغییر پس از چند لحظه در فضای مشترک ذخیره می‌شود و برای کاربران مجاز دیگر نیز به‌صورت زنده دریافت خواهد شد. نسخهٔ پشتیبان JSON را برای بازیابی مستقل نگه دارید.</div></div>`;}
  function render(){nav();fillYears();const names={dashboard:'داشبورد',companies:'شرکت‌ها',environment:'محیط زیست',health:'بهداشت',safety:'ایمنی',crisis:'مدیریت بحران',fire:'آتش‌نشانی',criteria:'مدیریت بندها',data:'پشتیبان و داده‌ها'};$('#pageCrumb').textContent=names[view]||'داشبورد';const main=$('#main');main.innerHTML=view==='dashboard'?dashboard():view==='companies'?companiesPage():['environment','health','safety','crisis','fire'].includes(view)?sectionPage(view):view==='criteria'?criteriaPage():dataPage();}
  function showModal(title,body,submitLabel='ذخیره',onSubmit=null){const root=$('#overlay');root.hidden=false;root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body">${body}</div><div class="modal-actions"><button class="btn btn-primary" id="modalSubmit">${submitLabel}</button><button class="btn btn-outline" data-action="close-modal">انصراف</button></div></section></div>`;$('#modalSubmit').onclick=()=>onSubmit?.();setTimeout(()=>$('#overlay input:not([type=hidden]),#overlay textarea')?.focus(),50);}
  function closeModal(){const root=$('#overlay');root.hidden=true;root.innerHTML='';}
  function addCriterionForm(sectionId,existing=null,initialCategory=null){
    const s=section(sectionId);
    const existingWeight=existing?weight(store.year,existing):'';
    showModal(existing?'ویرایش بند ممیزی':`افزودن بند به ${esc(s.name)}`,`<div class="field"><label>عنوان یا متن کامل بند</label><textarea id="criterionQuestion" placeholder="متن دقیق بند ممیزی را بنویسید…">${esc(existing?.question||'')}</textarea></div><div class="field"><label>وزن بند از مجموع ۱۰۰</label><input id="criterionWeight" type="number" min="0" max="100" step="0.0001" placeholder="مثلاً ۴" value="${existing?String(existingWeight):''}"></div><div class="field"><label>دسته/زیرعنوان (اختیاری)</label><input id="criterionCategory" placeholder="مثلاً مدیریت پسماند" value="${esc(existing?.categoryName||initialCategory||'')}"></div><p class="panel-subtitle">مجموع وزن‌های محیط‌زیست ۱۰۰ می‌ماند؛ با تغییر وزن این بند، سایر وزن‌ها متناسب تعدیل می‌شوند. نمرهٔ بند = نتیجهٔ ارزیابی × وزن بند.</p>`,existing?'ذخیرهٔ ویرایش':'افزودن بند',()=>{
      const question=$('#criterionQuestion').value.trim();
      const weightText=$('#criterionWeight').value;
      const weightValue=weightText===''?0:Number(weightText);
      const categoryName=$('#criterionCategory').value.trim()||s.name;
      const matchingCategory=allCriteria(sectionId).find(x=>x.id!==existing?.id&&x.categoryName===categoryName);
      const categoryId=matchingCategory?.categoryId||(existing?.categoryName===categoryName?existing.categoryId:`custom-cat-${sectionId}-${encodeURIComponent(categoryName)}`);
      if(!question){toast('متن بند را وارد کنید.','error');return;}
      if(!Number.isFinite(weightValue)||weightValue<0||(sectionId==='environment'&&weightValue>100)){toast('وزن باید عددی بین صفر و ۱۰۰ باشد.','error');return;}
      if(sectionId==='environment')enforceAllEnvironmentWeights();
      if(existing){
        const updated={question,categoryName,categoryId};
        if(store.addedCriteria.some(x=>x.id===existing.id)){const target=store.addedCriteria.find(x=>x.id===existing.id);Object.assign(target,updated);if(sectionId!=='environment')target.weight=weightText===''?null:weightValue;}
        else {const previous=store.criteriaOverrides[existing.id]||{};const next={...previous,...updated};if(sectionId!=='environment')next.weight=weightText===''?null:weightValue;if(Object.keys(next).length)store.criteriaOverrides[existing.id]=next;else delete store.criteriaOverrides[existing.id];}
        if(sectionId==='environment')setBalancedWeight(store.year,existing.id,weightValue);
      }else{
        const id=`custom-${Date.now()}`;store.addedCriteria.push({id,code:'جدید',sectionId,categoryId,categoryName,question,weight:sectionId==='environment'?0:(weightText===''?null:weightValue),ratings:{}});if(sectionId==='environment')setBalancedWeight(store.year,id,weightValue);
      }
      persist();closeModal();render();toast(existing?'بند ویرایش شد.':'بند جدید اضافه شد.');
    });
  }
  function deleteCriterion(sectionId,item){
    if(sectionId==='environment'&&allCriteria(sectionId).length<=1){toast('برای حفظ مجموع وزن ۱۰۰، آخرین بند فعال محیط‌زیست قابل حذف نیست.','error');return;}
    showModal('تأیید حذف بند',`<p>آیا مطمئن هستید این بند حذف شود؟</p><div class="notice"><div><strong>${esc(item.code||'بند جدید')} · ${esc(sectionNames[sectionId])}</strong>${esc(item.question)}</div></div><p class="panel-subtitle">${sectionId==='environment'?'وزن این بند در هر سال به‌طور مساوی بین چهار بند باقی‌مانده با بیشترین وزن توزیع می‌شود تا مجموع دقیقاً ۱۰۰ بماند. ':''}حذف و نمره‌های مرتبط در فضای کاری ذخیره می‌شود.</p>`,'حذف بند',()=>{
      if(sectionId==='environment')redistributeDeletedWeight(item);
      store.addedCriteria=store.addedCriteria.filter(x=>x.id!==item.id);
      if(!store.deletedCriteria.includes(item.id))store.deletedCriteria.push(item.id);
      delete store.criteriaOverrides[item.id];
      for(const key of Object.keys(store.weightOverrides))if(key.endsWith(`|${item.id}`))delete store.weightOverrides[key];
      for(const key of Object.keys(store.overrides))if(key.endsWith(`|${item.id}`))delete store.overrides[key];
      for(const key of Object.keys(store.comments))if(key.endsWith(`|${item.id}`))delete store.comments[key];
      persist();closeModal();render();toast(sectionId==='environment'?'بند حذف و وزنش بین چهار بند سنگین‌تر توزیع شد.':'بند حذف شد و از محاسبه خارج شد.');
    });
    const submit=$('#modalSubmit');submit.classList.remove('btn-primary');submit.classList.add('btn-danger');
  }
  function addCompany(){showModal('افزودن شرکت به فهرست',`<div class="field"><label>نام شرکت</label><input id="newCompanyName" placeholder="نام شرکت پتروشیمی"></div>`, 'افزودن شرکت',()=>{const name=$('#newCompanyName').value.trim();if(!name){toast('نام شرکت را وارد کنید.','error');return;}if(allCompanies().some(x=>x.name===name)){toast('این شرکت از قبل در فهرست وجود دارد.','error');return;}store.addedCompanies.push({id:`custom-company-${Date.now()}`,name,scores:{}});persist();closeModal();render();toast('شرکت اضافه شد.');});}
  function addYear(){showModal('افزودن سال ممیزی',`<div class="field"><label>سال (مثلاً ۱۴۰۶ را به صورت 1406 وارد کنید)</label><input id="newYearValue" inputmode="numeric" placeholder="1406" value=""></div><p class="panel-subtitle">سال جدید با فهرست همین شرکت‌ها آغاز می‌شود و نمره‌های قبلی به آن کپی نمی‌شوند.</p>`,'ایجاد سال',()=>{const y=$('#newYearValue').value.trim().replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d));if(!/^1\d{3}$/.test(y)){toast('سال را به شکل چهاررقمی وارد کنید.','error');return;}if(!store.years.includes(y))store.years.push(y);store.year=y;persist();closeModal();render();toast(`سال ${y} ایجاد شد.`);});}
  function companyReport(companyId,sectionId='environment'){
    const company=allCompanies().find(c=>c.id===companyId);if(!company){toast('شرکت موردنظر پیدا نشد.','error');return;}
    const s=section(sectionId),items=allCriteria(sectionId),info=scoreInfo(store.year,companyId,sectionId);
    const rows=items.map((it,index)=>{const result=rating(store.year,companyId,it,sectionId),w=Number(weight(store.year,it))||0,points=result===null||result===''||!Number.isFinite(Number(result))?null:Number(result)*w,comment=commentText(store.year,companyId,it.id);return `<tr><td class="company-report-num">${fmt(index+1)}</td><td><strong>${esc(it.code||'بند جدید')}</strong><br>${esc(it.question)}</td><td class="company-report-weight">${fmtWeight(w)}</td><td>${result===null||result===''?'—':fmt(result)}</td><td class="company-report-points">${points===null?'—':fmt(points)}</td><td class="company-report-comment">${comment?esc(comment):'—'}</td></tr>`}).join('');
    const originalTitle=document.title;
    $('#printRoot').innerHTML=`<article class="report-print company-report"><header class="report-header"><div><div class="company-report-brand">پایش‌بان · گزارش رسمی ممیزی</div><h1>گزارش تفصیلی ممیزی محیط‌زیست</h1><p>مرکز بهداشت، ایمنی و محیط زیست · منطقه ویژه اقتصادی انرژی پارس</p></div><div class="report-meta">سال ممیزی: ${esc(store.year)}<br>تاریخ تهیه: ${new Date().toLocaleDateString('fa-IR')}</div></header><section class="company-report-summary"><div><small>شرکت</small><strong>${esc(company.name)}</strong></div><div><small>نمرهٔ کل</small><strong>${info.score===null?'—':fmt(info.score)} <em>از ۱۰۰</em></strong></div><div><small>مجموع وزن بندها</small><strong>${fmtWeight(totalWeight(store.year,sectionId))} <em>از ۱۰۰</em></strong></div></section><p class="company-report-formula">امتیاز هر بند = نتیجهٔ ارزیابی × وزن بند · نمرهٔ کل = مجموع امتیاز بندها</p><table class="company-report-table"><thead><tr><th>ردیف</th><th>عنوان بند ممیزی</th><th>وزن</th><th>نتیجه ارزیابی</th><th>امتیاز بند</th><th>توضیحات ارزیاب</th></tr></thead><tbody>${rows||'<tr><td colspan="6">بندی برای این حوزه تعریف نشده است.</td></tr>'}</tbody><tfoot><tr><th colspan="2">جمع / نمرهٔ نهایی</th><th>${fmtWeight(totalWeight(store.year,sectionId))}</th><td>—</td><th>${info.score===null?'—':fmt(info.score)}</th><td>—</td></tr></tfoot></table><footer class="company-report-footer"><span>سامانهٔ پایش‌بان · گزارش اختصاصی ${esc(company.name)}</span><span>سال ${esc(store.year)} · مجموع وزن‌ها ۱۰۰</span></footer></article>`;
    document.title=`گزارش ممیزی ${company.name} ${store.year}`;window.print();setTimeout(()=>{document.title=originalTitle;},1000);
  }
  function report(sectionId){
    const s=section(sectionId),companies=allCompanies(),rank=ratedCompanies(store.year,sectionId),mean=avgScore(rank),criteria=allCriteria(sectionId);
    const bars=rank.map(x=>`<div class="report-bar-row"><span>${esc(x.company.name)}</span><div class="report-bar-track"><div class="report-bar-fill" style="width:${Math.max(0,Math.min(100,x.score))}%"></div></div><strong>${fmt(x.score)}</strong></div>`).join('');
    const table=companies.map(c=>{const x=scoreInfo(store.year,c.id,sectionId);return `<tr><td>${esc(c.name)}</td><td>${x.score===null?'—':fmt(x.score)}</td><td>${x.seeded?'محاسبه از بندها':x.zeroDefault?'شروع از صفر · محاسبه از بندها':x.legacy?'فقط نمره کل اکسل':x.hasCalculated?'ثبت کاربر':'ثبت نشده'}</td></tr>`}).join('');
    const categories=[];for(const it of criteria){let g=categories.find(x=>x.id===it.categoryId);if(!g){g={id:it.categoryId,name:it.categoryName||'سایر بندها',items:[]};categories.push(g);}g.items.push(it);}
    const detail=categories.map(group=>`<section class="report-detail-group"><h2>${esc(group.name)} · ${esc(s.name)}</h2><p class="report-detail-note">امتیاز هر سلول = نتیجهٔ ارزیابی × وزن همان بند. «—» یعنی برای آن شرکت/بند نمره‌ای ثبت نشده است.</p><div class="report-detail-wrap"><table class="report-detail-table"><thead><tr><th class="detail-company">شرکت</th>${group.items.map(it=>`<th><span class="detail-code">${esc(it.code||'بند')}</span><span class="detail-title">${esc(it.question)}</span><small>وزن: ${fmtWeight(weight(store.year,it))}</small></th>`).join('')}<th class="detail-sum">جمع این دسته</th></tr></thead><tbody>${companies.map(c=>{let subtotal=0,hasScore=false;const cells=group.items.map(it=>{const r=rating(store.year,c.id,it,sectionId),w=Number(weight(store.year,it));if(r===null||r===''||!Number.isFinite(Number(r))||!Number.isFinite(w)||w<=0)return '<td class="detail-empty">—</td>';const points=Number(r)*w;subtotal+=points;hasScore=true;return `<td><strong>${fmt(points)}</strong><small>نتیجه: ${fmt(r)}</small></td>`}).join('');return `<tr><th class="detail-company">${esc(c.name)}</th>${cells}<td class="detail-sum">${hasScore?fmt(subtotal):'—'}</td></tr>`}).join('')}</tbody></table></div></section>`).join('');
    $('#printRoot').innerHTML=`<div class="report-print"><div class="report-header"><div><h1>گزارش ممیزی ${esc(s.name)} شرکت‌های پتروشیمی عسلویه</h1><p>مرکز بهداشت، ایمنی و محیط زیست · منطقه ویژه اقتصادی انرژی پارس</p></div><div class="report-meta">سال ممیزی: ${esc(store.year)}<br>تاریخ تهیه: ${new Date().toLocaleDateString('fa-IR')}</div></div><div class="report-kpis"><div class="report-kpi"><small>تعداد شرکت در فهرست</small><strong>${fmt(companies.length)}</strong></div><div class="report-kpi"><small>دارای نمره</small><strong>${fmt(rank.length)}</strong></div><div class="report-kpi"><small>میانگین امتیاز ثبت‌شده</small><strong>${mean===null?'—':fmt(mean)}</strong></div></div><div class="report-chart"><h2>مقایسهٔ امتیاز کل شرکت‌ها — ${esc(s.name)}</h2><div class="report-bars">${bars||'<p>در این سال هنوز نمره‌ای ثبت نشده است.</p>'}</div></div><div class="report-table-wrap"><h2>خلاصهٔ نمرهٔ کل شرکت‌ها</h2><table class="report-table"><thead><tr><th>شرکت</th><th>نمرهٔ کل</th><th>وضعیت داده</th></tr></thead><tbody>${table}</tbody></table></div><div class="report-detail-intro"><h2>ریز نمرات شرکت‌ها به تفکیک بند ممیزی</h2><p>در جدول‌های بعدی، سطرها شرکت‌ها و ستون‌ها عناوین بندهای هر دسته هستند. هر خانه امتیاز کسب‌شده را همراه با نتیجهٔ ارزیابی نشان می‌دهد.</p></div>${detail||'<p>برای این بخش هنوز بندی تعریف نشده است.</p>'}<div class="report-footer"><span>سامانهٔ پایش‌بان · گزارش خودکار ممیزی</span><span>نمرهٔ کل = مجموع امتیاز بندها = مجموع (نتیجهٔ ارزیابی × وزن بند)</span></div></div>`;
    window.print();
  }
  function exportData(){const payload={app:'پایش‌بان',version:1,exportedAt:new Date().toISOString(),store};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`payeshban-backup-${store.year}.json`;a.click();URL.revokeObjectURL(a.href);toast('نسخهٔ پشتیبان آماده شد.');}
  function importData(file){const rd=new FileReader();rd.onload=()=>{try{const data=JSON.parse(rd.result);const st=data.store||data;if(!st||!st.years||!st.overrides)throw new Error('bad');store={...structuredClone(defaultState),...st};persist();render();toast('نسخهٔ پشتیبان بازیابی شد.');}catch{toast('ساختار فایل پشتیبان معتبر نیست.','error');}};rd.readAsText(file);}
  document.addEventListener('click',e=>{const viewBtn=e.target.closest('[data-view]');if(viewBtn){view=viewBtn.dataset.view;companyQuery='';if(view==='environment'&&!selectedCompany)selectedCompany=allCompanies()[0]?.id;render();$('#main').focus();$('#sidebar').classList.remove('open');$('#overlay').hidden=true;return;}const comp=e.target.closest('.company-card[data-company],.company-list-item[data-company]');if(comp){selectedCompany=comp.dataset.company;view='environment';render();return;}const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(action==='company-report')companyReport(a.dataset.reportCompany||selectedCompany);if(action==='report')report(a.dataset.section||'environment');if(action==='add-criterion')addCriterionForm(a.dataset.section||sectionFilter,null,a.dataset.categoryName||null);if(action==='edit-criterion'){const sid=a.dataset.section||sectionFilter;const it=allCriteria(sid).find(x=>x.id===a.dataset.id);if(it)addCriterionForm(sid,it);}if(action==='delete-criterion'){const sid=a.dataset.section||sectionFilter;const it=allCriteria(sid).find(x=>x.id===a.dataset.id);if(it)deleteCriterion(sid,it);}if(action==='add-company')addCompany();if(action==='new-year')addYear();if(action==='close-modal')closeModal();if(action==='export-data')exportData();if(action==='focus-score'){$('.score-panel')?.scrollIntoView({behavior:'smooth',block:'start'});toast('تغییرات به‌صورت خودکار ذخیره می‌شوند.');}});
  function refreshCurrentScore(companyId){
    const info=scoreInfo(store.year,companyId,'environment');
    const total=$('.score-total strong');if(total)total.textContent=fmt(info.score);
    const sub=$('.score-total small');if(sub)sub.textContent=`${info.hasCalculated?'محاسبه‌شده از بندها':'امتیاز کل ثبت‌شده'} از ${fmt(info.max||100)}`;
    const progress=$('.audit-progress .progress-fill');const label=$('.audit-progress span');
    if(progress){progress.style.width=`${info.totalItems?info.answered/info.totalItems*100:0}%`;if(label)label.textContent=`${fmt(info.answered)} از ${fmt(info.totalItems)} بند وزن‌دار نمره‌گذاری شده`;}
  }
  function refreshCriterionRow(itemId,companyId){
    const item=allCriteria('environment').find(x=>x.id===itemId);if(!item)return;
    const row=$(`[data-criterion-row="${CSS.escape(itemId)}"]`);if(!row)return;
    const result=rating(store.year,companyId,item);const weightValue=weight(store.year,item);const criterionWeight=Number(weightValue);
    const points=result!==null&&result!==''&&Number.isFinite(criterionWeight)&&criterionWeight>0?Number(result)*criterionWeight:null;
    const pointNode=row.querySelector('[data-points]');if(pointNode)pointNode.textContent=fmt(points);
    const category=allCriteria('environment').filter(x=>x.categoryId===item.categoryId).reduce((sum,x)=>sum+(Number(weight(store.year,x))||0),0);
    const categoryNode=$(`[data-category-weight="${CSS.escape(item.categoryId)}"]`);if(categoryNode)categoryNode.textContent=fmtWeight(category);
    const note=row.querySelector('.criterion-note');if(note&&criterionWeight>0)note.remove();else if(note)note.textContent='وزن این بند صفر است؛ برای تخصیص وزن، مقدار را ویرایش کنید.';
    refreshCurrentScore(companyId);
  }
  document.addEventListener('focusin',e=>{if(e.target.matches('[data-rating]'))e.target.select();});
  document.addEventListener('input',e=>{
    if(e.target.id==='companySearch'){companyQuery=e.target.value;render();const x=$('#companySearch');x?.focus();x?.setSelectionRange(companyQuery.length,companyQuery.length);return;}
    if(e.target.matches('[data-rating]')){
      const el=e.target;const normalized=normalizeDecimalInput(el.value);if(normalized!==el.value)el.value=normalized;const val=parseRatingInput(normalized);
      if(val!==null&&(!Number.isFinite(val)||val<0||val>1)){el.setCustomValidity('نتیجهٔ ارزیابی باید عددی بین ۰ و ۱ باشد؛ رقم فارسی یا انگلیسی وارد کنید.');el.reportValidity();return;}
      el.setCustomValidity('');const k=`${store.year}|${el.dataset.company}|${el.dataset.rating}`;
      if(val===null)delete store.overrides[k];else store.overrides[k]=val;
      persist();refreshCriterionRow(el.dataset.rating,el.dataset.company);return;
    }
    if(e.target.matches('[data-comment]')){
      const el=e.target,value=el.value.slice(0,2000);if(value!==el.value)el.value=value;const key=commentKey(store.year,el.dataset.company,el.dataset.comment);if(value)store.comments[key]=value;else delete store.comments[key];const count=$(`[data-comment-counter="${CSS.escape(key)}"]`);if(count)count.textContent=fmt(value.length);persist();return;
    }
  });
  document.addEventListener('change',e=>{if(e.target.matches('[data-weight]')){const el=e.target,raw=el.value.trim(),value=raw===''?0:Number(raw);if(!Number.isFinite(value)||value<0||value>100){el.setCustomValidity('وزن باید بین صفر و ۱۰۰ باشد');el.reportValidity();return;}el.setCustomValidity('');setBalancedWeight(store.year,el.dataset.weight,value);persist();render();return;}if(e.target.id==='yearSelect'){store.year=e.target.value;persist();render();}if(e.target.id==='companyFilter'){companyFilter=e.target.value;render();}if(e.target.id==='sectionFilter'){sectionFilter=e.target.value;render();}if(e.target.id==='importFile'&&e.target.files[0])importData(e.target.files[0]);});
  $('#newYearBtn').addEventListener('click',addYear);$('#logoutBtn').addEventListener('click',async()=>{if(!cloudClient)return;const {error}=await cloudClient.auth.signOut();if(error)toast('خروج از حساب انجام نشد.','error');});$('#mobileMenu').addEventListener('click',()=>{const s=$('#sidebar');s.classList.add('open');$('#overlay').hidden=false;$('#overlay').onclick=e=>{if(e.target.id==='overlay'){s.classList.remove('open');$('#overlay').hidden=true;}};});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  startAuth();
})();
